css:
.premium-toggle {
  --toggle-size: 3.5em;
  --toggle-padding: 0.4em;
  --handle-size: 2.2em;
  --track-height: 1em;

  --off-light: #e2e8f0;
  --off-dark: #94a3b8;
  --off-shadow: #64748b;

  --on-primary: #3f5efb;
  --on-secondary: #fc466b;
  --on-highlight: #5e72eb;
  --on-shadow: #333;

  position: relative;
  display: inline-block;
  width: calc(var(--toggle-size) * 2);
  height: var(--toggle-size);
  user-select: none;
}

.premium-toggle input {
  opacity: 0;
  width: 0;
  height: 0;
}

.switch {
  position: absolute;
  inset: 0;
  cursor: pointer;
}

.track {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: var(--track-height);
  transform: translateY(-50%);
  border-radius: var(--track-height);
  background: linear-gradient(to bottom, var(--off-light), var(--off-dark));
  box-shadow:
    0 0.05em 0.1em rgba(0, 0, 0, 0.1) inset,
    0 -0.05em 0.1em rgba(255, 255, 255, 0.1) inset,
    0 0.1em 0.2em rgba(0, 0, 0, 0.2);
  transition: all 0.4s cubic-bezier(0.3, 1.5, 0.7, 1);
  overflow: hidden;
}

.track-shadow {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    rgba(0, 0, 0, 0.1),
    rgba(0, 0, 0, 0),
    rgba(0, 0, 0, 0.1)
  );
  opacity: 0.5;
  transition: opacity 0.4s ease;
}

.premium-toggle input:checked ~ .switch .track {
  background: linear-gradient(to right, var(--on-primary), var(--on-secondary));
  box-shadow:
    0 0.05em 0.1em rgba(0, 0, 0, 0.2) inset,
    0 -0.05em 0.1em rgba(255, 255, 255, 0.1) inset,
    0 0.1em 0.5em rgba(63, 94, 251, 0.5);
}

.premium-toggle input:checked ~ .switch .track-shadow {
  opacity: 0.7;
}

.magnetic-field {
  position: absolute;
  inset: -50%;
  border-radius: 50%;
  background: radial-gradient(
    ellipse at center,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0) 70%,
    rgba(255, 255, 255, 0.2) 100%
  );
  opacity: 0;
  transform: scale(0.5);
  pointer-events: none;
  transition:
    opacity 0.6s ease,
    transform 0.6s ease;
}

.premium-toggle input:checked ~ .switch .magnetic-field {
  opacity: 1;
  transform: scale(1);
}

.handle-container {
  position: absolute;
  top: 50%;
  left: var(--toggle-padding);
  width: var(--handle-size);
  height: var(--handle-size);
  transform: translateY(-50%);
  transition: all 0.4s cubic-bezier(0.3, 1.5, 0.7, 1);
}

.premium-toggle input:checked ~ .switch .handle-container {
  left: calc(100% - var(--handle-size) - var(--toggle-padding));
}

.handle {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--off-light), var(--off-dark));
  box-shadow:
    0.15em 0.15em 0.3em var(--off-shadow),
    -0.1em -0.1em 0.2em rgba(255, 255, 255, 0.8);
  transition: all 0.4s cubic-bezier(0.3, 1.5, 0.7, 1);
  overflow: hidden;
}

.premium-toggle input:checked ~ .switch .handle {
  background: linear-gradient(145deg, var(--on-highlight), var(--on-primary));
  box-shadow:
    0.15em 0.15em 0.3em var(--on-shadow),
    -0.1em -0.1em 0.2em rgba(255, 255, 255, 0.2),
    0 0 0.5em rgba(63, 94, 251, 0.5);
}

.handle-inner {
  position: absolute;
  inset: 0.1em;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--off-light) 30%, var(--off-dark));
  transition: all 0.4s cubic-bezier(0.3, 1.5, 0.7, 1);
  overflow: hidden;
}

.premium-toggle input:checked ~ .switch .handle-inner {
  background: linear-gradient(
    145deg,
    var(--on-highlight) 30%,
    var(--on-primary)
  );
}

.handle-shine {
  position: absolute;
  top: 0.1em;
  left: 0.1em;
  width: 40%;
  height: 40%;
  border-radius: 50%;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.8),
    rgba(255, 255, 255, 0)
  );
  opacity: 0.8;
  transition: all 0.4s ease;
}

.premium-toggle input:checked ~ .switch .handle-shine {
  opacity: 0.4;
  transform: scale(0.7) translate(0.1em, 0.1em);
}

.handle-texture {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(
      circle at 30% 30%,
      rgba(255, 255, 255, 0.1) 0%,
      rgba(255, 255, 255, 0) 8%
    ),
    radial-gradient(
      circle at 70% 70%,
      rgba(0, 0, 0, 0.1) 0%,
      rgba(0, 0, 0, 0) 8%
    );
  background-size: 0.8em 0.8em;
  opacity: 0.3;
}

.handle-ripple {
  position: absolute;
  inset: -20%;
  border-radius: 50%;
  border: 0.2em solid rgba(255, 255, 255, 0.5);
  opacity: 0;
  transform: scale(0);
  pointer-events: none;
}

.premium-toggle input:checked ~ .switch .handle-ripple {
  animation: ripple 0.6s ease-out;
}

@keyframes ripple {
  0% {
    opacity: 0.7;
    transform: scale(0);
  }
  100% {
    opacity: 0;
    transform: scale(1);
  }
}

.sun-moon {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  overflow: hidden;
  transition: all 0.6s cubic-bezier(0.3, 1.5, 0.7, 1);
}

.ray {
  position: absolute;
  background-color: #f59e0b;
  width: 0.2em;
  height: 0.8em;
  left: 50%;
  top: 50%;
  opacity: 1;
  transform-origin: bottom center;
  transition: all 0.4s ease 0.1s;
}

.ray1 {
  transform: translate(-50%, -120%) rotate(0deg);
}
.ray2 {
  transform: translate(-50%, -120%) rotate(45deg);
}
.ray3 {
  transform: translate(-50%, -120%) rotate(90deg);
}
.ray4 {
  transform: translate(-50%, -120%) rotate(135deg);
}

.premium-toggle input:checked ~ .switch .ray {
  opacity: 0;
  transform: translate(-50%, -120%) rotate(180deg);
}

.crater {
  position: absolute;
  background-color: rgba(0, 0, 0, 0.2);
  border-radius: 50%;
  opacity: 0;
  transition: opacity 0.4s ease;
}

.crater1 {
  width: 0.3em;
  height: 0.3em;
  top: 30%;
  left: 30%;
}

.crater2 {
  width: 0.2em;
  height: 0.2em;
  top: 60%;
  left: 60%;
}

.crater3 {
  width: 0.25em;
  height: 0.25em;
  top: 40%;
  left: 70%;
}

.premium-toggle input:checked ~ .switch .crater {
  opacity: 1;
  transition: opacity 0.4s ease 0.2s;
}

.wave-group {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  transform: scale(0);
  overflow: hidden;
  transition: transform 0.4s ease;
}

.premium-toggle input:checked ~ .switch .wave-group {
  transform: scale(1);
}

.wave {
  position: absolute;
  left: -50%;
  right: -50%;
  height: 200%;
  background: linear-gradient(
    90deg,
    rgba(252, 70, 107, 0) 0%,
    rgba(252, 70, 107, 0.3) 50%,
    rgba(63, 94, 251, 0.3) 50%,
    rgba(63, 94, 251, 0) 100%
  );
  opacity: 0;
  transform: translateY(100%);
}

.premium-toggle input:checked ~ .switch .wave {
  animation: wave 1.5s linear infinite;
  opacity: 0.3;
}

.wave2 {
  animation-delay: 0.5s !important;
}

.wave3 {
  animation-delay: 1s !important;
}

@keyframes wave {
  0% {
    transform: translateY(100%);
  }
  100% {
    transform: translateY(-100%);
  }
}

.premium-toggle:active .handle {
  transform: scale(0.9);
}

.premium-toggle input:focus ~ .switch .track {
  box-shadow:
    0 0.05em 0.1em rgba(0, 0, 0, 0.1) inset,
    0 -0.05em 0.1em rgba(255, 255, 255, 0.1) inset,
    0 0.1em 0.2em rgba(0, 0, 0, 0.2),
    0 0 0 0.2em rgba(59, 130, 246, 0.3);
}

.premium-toggle input:checked:focus ~ .switch .track {
  box-shadow:
    0 0.05em 0.1em rgba(0, 0, 0, 0.2) inset,
    0 -0.05em 0.1em rgba(255, 255, 255, 0.1) inset,
    0 0.1em 0.5em rgba(63, 94, 251, 0.5),
    0 0 0 0.2em rgba(59, 130, 246, 0.3);
}
